-- SQL Server schema and data migrated from the original MariaDB dump.
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;

CREATE TABLE dbo.author (
    id INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    firstName NVARCHAR(50) NOT NULL,
    lastName NVARCHAR(50) NOT NULL,
    bio NVARCHAR(MAX) NOT NULL,
    linkedinUrl NVARCHAR(100) NULL,
    photo NVARCHAR(MAX) NULL
);

CREATE TABLE dbo.articles (
    id INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    title NVARCHAR(255) NOT NULL,
    content NVARCHAR(MAX) NOT NULL,
    authorId INT NOT NULL,
    photo NVARCHAR(MAX) NULL,
    publishDate DATETIME2 NOT NULL CONSTRAINT DF_articles_publishDate DEFAULT SYSDATETIME(),
    CONSTRAINT FK_articles_author FOREIGN KEY (authorId) REFERENCES dbo.author (id)
);

CREATE TABLE dbo.users (
    id INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
    first NVARCHAR(25) NULL,
    last NVARCHAR(25) NULL,
    email NVARCHAR(100) NULL,
    password VARCHAR(100) NULL,
    active NVARCHAR(3) NOT NULL CONSTRAINT DF_users_active DEFAULT N'Yes',
    dateAdded DATETIME2 NOT NULL CONSTRAINT DF_users_dateAdded DEFAULT SYSDATETIME(),
    CONSTRAINT CK_users_active CHECK (active IN (N'Yes', N'No'))
);

SET IDENTITY_INSERT dbo.author ON;
INSERT INTO dbo.author ([id], [firstName], [lastName], [bio], [linkedinUrl], [photo])
